//! Text the scene cannot lay out by itself.
//!
//! GSP 1.9.0 wraps label text only at spaces, so unspaced Chinese runs past
//! the label's edge. [`wrap`] breaks lines itself, measuring with the advance
//! widths of the bundled Noto Sans SC (`metrics.rs`, generated by
//! `tools/fonts/build_fonts.py`), and the labels receive text with `\n`.
//! [`time`] formats clocks, ages and countdowns in Chinese.

mod metrics;
pub mod time;

use alloc::string::String;
use alloc::vec::Vec;

/// Width of `ch` at `size` px in the UI font (Noto Sans SC), in 1/64 px.
fn advance(ch: char, size: u32) -> u32 {
    let cp = ch as u32;
    let units = match metrics::NOTOSANSSC.binary_search_by_key(&cp, |&(c, _)| c) {
        Ok(i) => u32::from(metrics::NOTOSANSSC[i].1),
        // Ideographs, kana and anything unknown: one em.
        Err(_) => u32::from(metrics::NOTOSANSSC_UPEM),
    };
    units * size * 64 / u32::from(metrics::NOTOSANSSC_UPEM)
}

/// Width of `text` at `size` px, in whole pixels (rounded up).
pub fn width(text: &str, size: u32) -> u32 {
    text.chars()
        .map(|c| advance(c, size))
        .sum::<u32>()
        .div_ceil(64)
}

/// Characters that must not start a line.
fn no_line_start(ch: char) -> bool {
    "，。、：；！？）」』】》〉…—,.:;!?)]}%".contains(ch)
}

/// Characters that must not end a line.
fn no_line_end(ch: char) -> bool {
    "（「『【《〈“‘([{".contains(ch)
}

/// A word joins characters that must stay together: Latin letters, digits and
/// the punctuation inside paths, versions, commands and amounts.
fn joins(ch: char) -> bool {
    ch.is_ascii_alphanumeric() || "._-/:@#$%+~=&'`*<>\\|^".contains(ch)
}

/// Splits into breakable units: words, single other characters, and spaces.
fn units(text: &str) -> Vec<&str> {
    let mut out = Vec::new();
    let mut start = None;
    for (i, ch) in text.char_indices() {
        if joins(ch) {
            start.get_or_insert(i);
            continue;
        }
        if let Some(s) = start.take() {
            out.push(&text[s..i]);
        }
        out.push(&text[i..i + ch.len_utf8()]);
    }
    if let Some(s) = start {
        out.push(&text[s..]);
    }
    out
}

/// Greedy break into lines no wider than `limit` (1/64 px).
fn greedy(text: &str, size: u32, limit: u32) -> Vec<String> {
    let measure = |s: &str| s.chars().map(|c| advance(c, size)).sum::<u32>();
    let mut lines: Vec<String> = Vec::new();
    for paragraph in text.split('\n') {
        let mut line = String::new();
        let mut used = 0u32;
        for unit in units(paragraph) {
            let w = measure(unit);
            let space = unit.chars().all(char::is_whitespace);
            if line.is_empty() && space {
                continue;
            }
            if used + w <= limit {
                line.push_str(unit);
                used += w;
                continue;
            }
            if space {
                lines.push(String::from(line.trim_end()));
                line.clear();
                used = 0;
                continue;
            }
            let first = unit.chars().next().unwrap_or(' ');
            if no_line_start(first) && !line.is_empty() {
                // Hang closing punctuation rather than start a line with it.
                line.push_str(unit);
                used += w;
                continue;
            }
            if w > limit {
                // Wider than any line: break inside the word.
                for ch in unit.chars() {
                    let cw = advance(ch, size);
                    if used + cw > limit && !line.is_empty() {
                        lines.push(core::mem::take(&mut line));
                        used = 0;
                    }
                    line.push(ch);
                    used += cw;
                }
                continue;
            }
            // Break before this unit; a dangling opener moves down with it.
            let mut carry = String::new();
            if let Some(last) = line.chars().last().filter(|&c| no_line_end(c)) {
                line.pop();
                carry.push(last);
            }
            lines.push(String::from(line.trim_end()));
            line = carry;
            line.push_str(unit);
            used = measure(&line);
        }
        lines.push(String::from(line.trim_end()));
    }
    while lines.len() > 1 && lines.last().is_some_and(String::is_empty) {
        lines.pop();
    }
    lines
}

/// Breaks `text` into at most `max_lines` lines that fit `width_px` at
/// `size_px`, joined with `\n`. Avoids a last line of one or two characters
/// by narrowing the measure, and ends overflowing text with `…`.
pub fn wrap(text: &str, width_px: u32, size_px: u32, max_lines: usize) -> String {
    let text = collapse(text);
    let limit = width_px * 64;
    let mut lines = greedy(&text, size_px, limit);
    if lines.len() > 1 && lines.len() <= max_lines {
        let short = |ls: &[String]| ls.last().map_or(0, |l| l.chars().count()) < 4;
        if short(&lines) {
            let count = lines.len();
            for pct in (60..100).rev().step_by(4) {
                let trial = greedy(&text, size_px, limit * pct / 100);
                if trial.len() == count && !short(&trial) {
                    lines = trial;
                    break;
                }
            }
        }
    }
    if lines.len() > max_lines && max_lines > 0 {
        lines.truncate(max_lines);
        let last = lines.last_mut().expect("max_lines > 0");
        let ellipsis = advance('…', size_px);
        while !last.is_empty()
            && last.chars().map(|c| advance(c, size_px)).sum::<u32>() + ellipsis > limit
        {
            last.pop();
        }
        let kept = String::from(last.trim_end());
        *last = kept;
        last.push('…');
    }
    lines.join("\n")
}

/// One line of at most `width_px`, cut with `…` when it does not fit.
pub fn fit(text: &str, width_px: u32, size_px: u32) -> String {
    wrap(&collapse(text).replace('\n', " "), width_px, size_px, 1)
}

/// Collapses runs of whitespace (keeping single line breaks) and trims.
fn collapse(text: &str) -> String {
    let mut out = String::with_capacity(text.len());
    let mut space = false;
    let mut newline = false;
    for ch in text.trim().chars() {
        if ch == '\n' {
            newline = true;
            space = false;
            continue;
        }
        if ch.is_whitespace() {
            space = true;
            continue;
        }
        if newline {
            out.push('\n');
        } else if space {
            out.push(' ');
        }
        newline = false;
        space = false;
        out.push(ch);
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    fn lines(s: &str) -> Vec<&str> {
        s.split('\n').collect()
    }

    #[test]
    fn short_text_stays_on_one_line() {
        assert_eq!(wrap("给 Farol 选一种光", 420, 26, 2), "给 Farol 选一种光");
    }

    #[test]
    fn chinese_breaks_between_characters_and_fits() {
        let out = wrap(
            "首页的光球用哪种风格？三种都在模拟器里渲染过，截图在 docs/orbs。",
            400,
            19,
            3,
        );
        for line in lines(&out) {
            assert!(width(line, 19) <= 400, "{line} too wide");
        }
        assert!(lines(&out).len() >= 2);
        assert!(out.contains("docs/orbs"), "a path is never split: {out}");
    }

    #[test]
    fn closing_punctuation_never_starts_a_line() {
        let text = "一二三四五六七八九十一二三四五六七八九十，下一句";
        // 20 ideographs at 10 px fill 200 px exactly; the comma must not wrap alone.
        let out = wrap(text, 200, 10, 3);
        for line in lines(&out) {
            assert!(!line.starts_with('，'), "{out}");
        }
    }

    #[test]
    fn last_line_is_not_an_orphan() {
        let out = wrap("修复子 agent 调用失败，补回归测试", 420, 27, 2);
        let ls = lines(&out);
        assert_eq!(ls.len(), 2, "{out}");
        assert!(ls[1].chars().count() >= 4, "{out}");
    }

    #[test]
    fn overflow_ends_with_an_ellipsis_within_the_width() {
        let out = wrap(&"很长的内容".repeat(40), 300, 20, 2);
        let ls = lines(&out);
        assert_eq!(ls.len(), 2);
        assert!(ls[1].ends_with('…'));
        assert!(width(ls[1], 20) <= 300);
    }

    #[test]
    fn long_words_break_inside_when_they_cannot_fit() {
        let word = "a".repeat(200);
        let out = wrap(&word, 100, 16, 9);
        for line in lines(&out) {
            assert!(width(line, 16) <= 100);
        }
    }

    #[test]
    fn whitespace_collapses_and_newlines_are_kept() {
        assert_eq!(wrap("  a   b \n\n c ", 300, 16, 5), "a b\nc");
    }

    #[test]
    fn fit_is_one_line() {
        let out = fit("第一行\n第二行很长很长很长很长很长很长很长", 120, 16);
        assert!(!out.contains('\n'));
        assert!(out.ends_with('…'));
    }
}
